<script setup lang="ts">
import { onMounted,onUnmounted,ref } from 'vue'
import { ArrowUpRight,ArrowRight,Activity,CheckCheck,Timer,Zap,RefreshCw,Play,ArrowDownToLine,Info } from 'lucide-vue-next'
import StatCard from '../components/StatCard.vue'
import StatusTag from '../components/StatusTag.vue'
import TrendChart from '../components/TrendChart.vue'
import DemoRequestPanel from '../components/DemoRequestPanel.vue'
import { getOverview } from '../api/requests'
import { errorMessage } from '../api/http'
import type { OverviewData } from '../types'
const data=ref<OverviewData|null>(null),hours=ref(24),loading=ref(true),error=ref(''),testOpen=ref(false),updated=ref('')
const number=(v:number)=>new Intl.NumberFormat('zh-CN').format(v)
const tokens=(v:number)=>v>=1000?`${(v/1000).toFixed(1)}k`:number(v)
const percent=(v:number)=>`${v.toFixed(1)}%`
function time(date:string){return new Date(date).toLocaleTimeString('zh-CN',{hour12:false,hour:'2-digit',minute:'2-digit',second:'2-digit'})}
async function load(){loading.value=true;error.value='';try{data.value=await getOverview(hours.value);updated.value=new Date().toLocaleTimeString('zh-CN',{hour12:false})}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
function download(){if(!data.value)return;const blob=new Blob([JSON.stringify(data.value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='modelgate-overview-demo.json';a.click();URL.revokeObjectURL(url)}
onMounted(()=>{load();window.addEventListener('modelgate:refresh',load)})
onUnmounted(()=>window.removeEventListener('modelgate:refresh',load))
</script>
<template><section class="page-heading"><div><div class="title-line"><h1 class="page-title">网关总览</h1><span class="subtle-tag">DEMO</span></div><p class="page-subtitle">流量、模型与运行状态，一目了然。</p></div><div class="page-actions"><el-select v-model="hours" aria-label="统计时间范围" class="period-select" @change="load"><el-option :value="1" label="最近 1 小时"/><el-option :value="24" label="最近 24 小时"/><el-option :value="168" label="最近 7 天"/></el-select><button class="btn btn-secondary" :disabled="!data" @click="download"><ArrowDownToLine :size="15"/>导出报告</button></div></section><div v-if="error" class="error-state" role="alert">{{error}}<button class="text-link" @click="load">重新加载</button></div><el-skeleton v-if="loading&&!data" :rows="12" animated/><template v-else-if="data"><div class="demo-banner"><div><Info :size="16"/><span>你正在查看演示数据。发起测试请求，体验一次完整的网关调用。</span></div><button @click="testOpen=true">试一试<ArrowRight :size="14"/></button></div><div class="stats-grid"><StatCard label="总请求数" :value="number(data.requests)" description="当前时间范围内的所有请求"><template #icon><Activity :size="17"/></template></StatCard><StatCard label="请求成功率" :value="percent(data.success_rate)" description="成功完成的请求占比"><template #icon><CheckCheck :size="18"/></template></StatCard><StatCard label="P95 响应延迟" :value="number(Math.round(data.p95_latency_ms))" unit="ms" description="95% 的请求在此时间内完成"><template #icon><Timer :size="17"/></template></StatCard><StatCard label="Token 用量" :value="tokens(data.tokens)" description="输入与输出合计 · 模拟估算"><template #icon><Zap :size="17"/></template></StatCard></div><div class="overview-middle"><section class="panel traffic-panel"><div class="panel-head"><div><h2 class="panel-title">请求流量</h2><p class="panel-description">当前时间范围内的请求分布</p></div><div class="chart-legend"><span class="legend-line"></span>请求量</div></div><div class="chart-body"><TrendChart :series="data.series"/></div></section><section class="panel upstream-panel"><div class="panel-head"><h2 class="panel-title">上游状态</h2><RouterLink to="/providers" class="icon-btn" aria-label="查看供应商"><ArrowUpRight :size="17"/></RouterLink></div><div class="upstream-list"><div v-for="(provider,index) in data.providers" :key="provider.id" class="upstream-row"><span class="provider-avatar" :class="`provider-color-${index%3}`">{{provider.name.slice(0,1).toUpperCase()}}</span><div class="upstream-name"><strong>{{provider.name}}</strong><span>{{provider.kind}}</span></div><div class="upstream-health"><span class="status-tag" :class="provider.enabled?'healthy':'disabled'"><span class="status-dot"></span>{{provider.enabled?'正常':'停用'}}</span><small class="mono">{{provider.latency_ms}} ms</small></div></div></div><div class="upstream-summary"><span class="status-dot" :class="{'disabled-dot':!data.providers.some(p=>p.enabled)}"></span>{{data.providers.filter(p=>p.enabled).length}} / {{data.providers.length}} 个上游可用<RouterLink to="/model-routes" class="text-link">查看路由<ArrowRight :size="13"/></RouterLink></div></section></div><section class="panel recent-panel"><div class="panel-head"><div class="panel-title-with-count"><h2 class="panel-title">最近请求</h2><span class="count-badge">{{data.recent_requests.length}}</span></div><RouterLink to="/requests" class="text-link">查看全部<ArrowRight :size="14"/></RouterLink></div><div class="table-wrap"><table class="data-table"><thead><tr><th>请求 ID / 时间</th><th>模型</th><th>供应商</th><th>状态</th><th class="align-right">延迟</th><th class="align-right">Token</th><th class="align-right">模式</th></tr></thead><tbody><tr v-for="request in data.recent_requests.slice(0,5)" :key="request.id"><td><RouterLink :to="{path:'/requests',query:{q:request.id}}" class="request-id mono">{{request.id.slice(0,17)}}</RouterLink><small class="table-secondary mono">{{time(request.created_at)}}</small></td><td><span class="model-name">{{request.model}}</span></td><td>{{request.provider||'未分配'}}</td><td><StatusTag :status="request.status"/></td><td class="mono align-right">{{number(request.latency_ms)}}<span class="muted"> ms</span></td><td class="mono align-right">{{number(request.input_tokens+request.output_tokens)}}</td><td class="align-right"><span class="plain-tag">{{request.is_stream?'SSE':'JSON'}}</span></td></tr><tr v-if="!data.recent_requests.length"><td colspan="7" class="empty-state">还没有请求。点击“测试请求”开始体验。</td></tr></tbody></table></div></section><div class="overview-meta"><span><span class="status-dot"></span>演示网关已连接</span><span>数据更新于 {{updated}}<button class="icon-btn" :disabled="loading" aria-label="刷新数据" @click="load"><RefreshCw :size="13" :class="{'is-spinning':loading}"/></button></span></div></template><DemoRequestPanel v-model="testOpen"/></template>
